// Filled in by the setup script: the font files that were downloaded successfully.
const FONTS_OK = []

const S = CONFIG.settings
const WEEK = S.lang === 'uk'
  ? ['Нд', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб']
  : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const ARROWS = { doubleUp: '⇈', up: '↑', fortyFiveUp: '↗', flat: '→', fortyFiveDown: '↘', down: '↓', doubleDown: '⇊' }

// Docs spell the AOD level ONAL_AOD; both spellings are tried.
var LV = {
  normal: show_level.ONLY_NORMAL,
  aod: show_level.ONAL_AOD !== undefined ? show_level.ONAL_AOD : show_level.ONLY_AOD
}

function pad(n) { return n < 10 ? '0' + n : '' + n }
function num(hex) { return parseInt(hex.slice(1), 16) }
function safe(fn, fallback) {
  try {
    var v = fn()
    return v === undefined || v === null ? fallback : v
  } catch (e) {
    return fallback
  }
}
function fmtBg(mg) {
  if (mg === null || mg === undefined) return '--'
  return S.units === 'mmol' ? (mg / 18).toFixed(1) : '' + Math.round(mg)
}
function rangeColor(mg) {
  if (mg === null || mg === undefined) return S.cOk
  return mg < S.low ? S.cLow : mg > S.high ? S.cHigh : S.cOk
}

var step = null, heart = null, battery = null, weather = null
var items = []
var timer = null
var MAX_DOTS = 48

function makeText(e) {
  var p = {
    x: e.x, y: e.y, w: e.w, h: e.h,
    color: num(e.color), text_size: e.size,
    align_h: align.CENTER_H, align_v: align.CENTER_V,
    text_style: text_style.NONE, text: '',
    show_level: LV[e.screen]
  }
  if (e.fontFile && FONTS_OK.indexOf(e.fontFile) >= 0) p.font = 'fonts/' + e.fontFile
  var kind = widget.TEXT
  // Rotation needs the rotating text widget; falls back to plain TEXT if the firmware lacks it.
  if (e.rot && widget.TEXT_ROTATE) {
    kind = widget.TEXT_ROTATE
    p.angle = e.rot
    p.center_x = e.cx
    p.center_y = e.cy
  }
  return createWidget(kind, p)
}

function makeIcon(e) {
  if (!e.icon) return
  createWidget(widget.IMG, {
    x: e.icon.x, y: e.icon.y, w: e.icon.s, h: e.icon.s, src: e.icon.file, show_level: LV[e.screen]
  })
}

function yFor(e, mg) {
  var c = Math.max(S.gmin, Math.min(S.gmax, mg))
  return e.y + e.h - ((c - S.gmin) / (S.gmax - S.gmin)) * e.h
}

function makeGraph(e) {
  var line = function (mg) {
    createWidget(widget.FILL_RECT, {
      x: e.x, y: Math.round(yFor(e, mg)), w: e.w, h: 2, color: 0x444444, show_level: LV[e.screen]
    })
  }
  line(S.low)
  line(S.high)
  var dots = []
  for (var i = 0; i < MAX_DOTS; i++) {
    dots.push(createWidget(widget.FILL_RECT, {
      x: 0, y: 0, w: e.size, h: e.size, radius: e.size / 2, color: num(e.color), show_level: LV[e.screen]
    }))
  }
  return dots
}

function makeClick(e) {
  if (e.screen !== 'normal' || !e.action) return
  var w = Math.max(e.gw, 48)
  var h = Math.max(e.gh, 48)
  var p = { x: Math.round(e.cx - w / 2), y: Math.round(e.cy - h / 2), w: w, h: h, show_level: LV.normal }
  if (e.action === 'custom') {
    p.normal_src = 'click.png'
    p.press_src = 'click.png'
    p.click_func = function () {
      var id = String(e.appId).trim()
      if (/^[0-9]+$/.test(id)) safe(function () { launchApp({ appId: Number(id), native: false }) }, null)
      else safe(function () { launchApp({ url: id, native: true }) }, null)
    }
    createWidget(widget.BUTTON, p)
  } else {
    var names = e.alias || [e.action]
    var found
    for (var k = 0; k < names.length; k++) {
      if (data_type[names[k]] !== undefined) { found = data_type[names[k]]; break }
    }
    // Names the firmware does not know are skipped: the tap simply does nothing.
    if (found !== undefined) {
      p.src = 'click.png'
      p.type = found
      createWidget(widget.IMG_CLICK, p)
    }
  }
}

function drawGraph(it, d) {
  var e = it.e
  var pts = d.graph || []
  var span = S.hours * 3600000
  var now = Date.now()
  var shown = []
  for (var i = 0; i < pts.length; i++) {
    if (pts[i].ts >= now - span) shown.push(pts[i])
  }
  shown = shown.slice(-MAX_DOTS)
  for (var j = 0; j < MAX_DOTS; j++) {
    var dot = it.dots[j]
    if (j >= shown.length) {
      dot.setProperty(prop.VISIBLE, false)
      continue
    }
    var pt = shown[j]
    var x = e.x + ((pt.ts - (now - span)) / span) * (e.w - e.size)
    var props = {
      x: Math.round(x),
      y: Math.round(yFor(e, pt.bg) - e.size / 2)
    }
    if (e.byRange) props.color = num(rangeColor(pt.bg))
    dot.setProperty(prop.MORE, props)
    dot.setProperty(prop.VISIBLE, true)
  }
}

function textFor(e, d, now) {
  switch (e.type) {
    case 'hour': return pad(now.getHours())
    case 'minute': return pad(now.getMinutes())
    case 'second': return pad(now.getSeconds())
    case 'time': return pad(now.getHours()) + ':' + pad(now.getMinutes())
    case 'bg': return fmtBg(d.bg)
    case 'arrow': return ARROWS[d.trend] || '--'
    case 'ago':
      if (d.demo) return 'DEMO'
      if (!d.ts) return '--'
      return Math.max(0, Math.floor((now.getTime() - d.ts) / 60000)) + (S.lang === 'uk' ? ' хв' : ' min')
    case 'date': return pad(now.getDate()) + '.' + pad(now.getMonth() + 1)
    case 'day': return WEEK[now.getDay()]
    case 'weather':
      return safe(function () {
        var f = weather.getForecast().forecastData.data[0]
        return f.high + '°/' + f.low + '°'
      }, '--')
    case 'steps': return '' + safe(function () { return step.getCurrent() }, '--')
    case 'hr': return '' + safe(function () { return heart.getCurrent() || heart.getLast() }, '--')
    case 'wbat': return safe(function () { return battery.getCurrent() }, '--') + '%'
    case 'pbat': return d.phoneBattery === null || d.phoneBattery === undefined ? '--' : d.phoneBattery + '%'
    case 'label': return e.text || ''
  }
  return ''
}

function update() {
  var d = safe(getData, {}) || {}
  var now = new Date()
  for (var i = 0; i < items.length; i++) {
    var it = items[i]
    var e = it.e
    if (e.type === 'graph') {
      drawGraph(it, d)
      continue
    }
    var p = { text: textFor(e, d, now) }
    if (e.byRange && (e.type === 'bg' || e.type === 'arrow')) p.color = num(rangeColor(d.bg))
    it.w.setProperty(prop.MORE, p)
  }
}

WatchFace({
  build() {
    step = safe(function () { return new Step() }, null)
    heart = safe(function () { return new HeartRate() }, null)
    battery = safe(function () { return new Battery() }, null)
    weather = safe(function () { return new Weather() }, null)

    createWidget(widget.FILL_RECT, { x: 0, y: 0, w: 466, h: 466, color: num(S.bg), show_level: LV.normal })
    createWidget(widget.FILL_RECT, { x: 0, y: 0, w: 466, h: 466, color: 0x000000, show_level: LV.aod })

    var hasSeconds = false
    for (var i = 0; i < CONFIG.elements.length; i++) {
      var e = CONFIG.elements[i]
      if (e.type === 'second') hasSeconds = true
      if (e.type === 'graph') {
        items.push({ e: e, dots: makeGraph(e) })
      } else {
        makeIcon(e)
        items.push({ e: e, w: makeText(e) })
      }
    }
    // Tap areas go last so they sit on top of everything else.
    for (var j = 0; j < CONFIG.elements.length; j++) makeClick(CONFIG.elements[j])

    update()
    timer = setInterval(update, hasSeconds ? 1000 : 15000)
    // Minute tick; also the best chance of refreshing the AOD screen.
    safe(function () { new Time().onPerMinute(update) }, null)
  },
  onDestroy() {
    if (timer) clearInterval(timer)
  }
})
